(4, 13, '深圳磐石信息安全技术有限公司', NULL, '信息安全',      '100-499人', '深圳市南山区科技园南区', '磐石安全深耕网络安全攻防与合规咨询，为国家重点单位提供渗透测试、安全运营与等保建设服务，多次获得行业奖项。', 'https://www.panshi-sec.com',     'ACTIVE', 0, '2026-02-15 14:00:00', '2026-02-15 14:00:00'),
(5, 14, '上海极光人工智能科技有限公司', NULL, '人工智能',      '100-499人', '上海市徐汇区漕河泾开发区宜州路188号', '极光智能专注于自然语言处理与行业大模型应用落地，产品覆盖智能客服、知识管理与企业Copilot，研发人员占比70%以上。', 'https://www.aurora-ai.com',      'ACTIVE', 0, '2026-03-03 09:20:00', '2026-03-03 09:20:00'),
(6, 15, '广州星辰互动娱乐有限公司', NULL, '游戏/文娱',         '500-999人', '广州市天河区珠江新城华夏路30号', '星辰互娱专注精品手游与游戏平台研发，多款产品月流水破千万，拥有自研引擎与美术中台，团队年轻有活力。', 'https://www.xingchen-game.com',  'ACTIVE', 0, '2026-03-18 10:30:00', '2026-03-18 10:30:00');
INSERT INTO job (id, company_id, job_name, job_type, salary_min, salary_max, city, education, experience, description, requirements, status, view_count, deleted, create_time, update_time) VALUES
(1,  1, 'Java开发工程师',        '后端开发', 15, 25, '上海', '本科', '1-3年', '负责公司核心业务系统的后端设计与开发，参与需求评审、技术方案设计、代码编写与性能优化，保障系统稳定高效运行。', '1、计算机相关专业本科及以上学历；2、扎实的Java基础，熟悉JVM、并发编程；3、熟练使用Spring Boot、Spring Cloud等主流框架；4、熟悉MySQL、Redis，具备SQL调优经验；5、有分布式、高并发项目经验者优先。', 'ONLINE', 1286, 0, '2026-02-20 10:00:00', '2026-08-30 09:00:00'),
(2,  1, '高级Java后端工程师',    '后端开发', 25, 40, '上海', '本科', '3-5年', '负责高并发分布式系统的架构设计与核心模块研发，带领小组完成技术攻坚，推动团队技术演进与代码质量提升。', '1、5年以上Java开发经验，3年以上大型分布式系统经验；2、精通Spring Cloud微服务、消息队列、分布式缓存；3、熟悉Kubernetes容器化部署；4、具备优秀的系统设计能力与团队协作能力。', 'ONLINE', 863,  0, '2026-03-10 11:00:00', '2026-08-20 10:00:00'),
(3,  1, '前端开发工程师',        '前端开发', 13, 22, '上海', '本科', '1-3年', '负责公司Web管理端与门户网站的前端开发，与UI、后端协作实现高质量交互体验，推动前端工程化建设。', '1、本科及以上学历，2年以上前端经验；2、精通Vue3、TypeScript、Vite；3、熟悉Element Plus、ECharts等组件库；4、了解前端工程化、性能优化。', 'ONLINE', 754,  0, '2026-03-15 09:30:00', '2026-09-01 14:00:00'),
(4,  2, 'Python后端开发工程师',  '后端开发', 18, 30, '杭州', '本科', '1-3年', '负责电商平台交易、营销系统的后端研发，使用Python进行服务开发与数据接口建设，参与推荐与风控策略落地。', '1、本科及以上学历，扎实的Python基础；2、熟悉Django/Flask/FastAPI任一框架；3、熟悉MySQL、Redis、消息队列；4、有电商或高并发经验优先。', 'ONLINE', 682,  0, '2026-03-22 10:00:00', '2026-09-02 09:00:00'),
(5,  2, '电商运营专员',          '运营',      8, 13, '杭州', '大专', '1-3年', '负责店铺日常运营、活动策划与数据分析，提升店铺流量与转化率，对接平台小二与供应链团队。', '1、大专及以上学历，有电商平台运营经验；2、熟悉主流电商平台规则；3、具备良好的数据分析与沟通能力。', 'ONLINE', 521,  0, '2026-04-01 09:00:00', '2026-08-15 10:00:00'),
(6,  2, '数据分析师',            '数据分析', 15, 25, '杭州', '本科', '1-3年', '负责业务数据分析、报表体系搭建与专题分析，通过数据驱动运营决策，输出可落地的增长建议。', '1、统计学/数学/计算机相关专业；2、精通SQL，熟悉Python分析工具；3、掌握Tableau/PowerBI等可视化工具；4、有电商数据分析经验优先。', 'ONLINE', 612,  0, '2026-04-10 14:00:00', '2026-09-03 11:00:00'),
(7,  3, '大数据开发工程师',      '大数据',   20, 35, '北京', '本科', '3-5年', '负责大数据平台的数据采集、处理与计算框架开发，建设离线和实时数据链路，支撑数据中台业务。', '1、本科及以上学历，3年以上大数据开发经验；2、精通Hadoop、Spark、Flink；3、熟悉Kafka、Hive、HBase；4、有数据仓库建设经验者优先。', 'ONLINE', 456,  0, '2026-04-15 09:30:00', '2026-08-25 09:00:00'),
(8,  3, '数据仓库工程师',        '大数据',   18, 30, '北京', '本科', '1-3年', '负责数仓模型设计、ETL开发与数据质量管理，保障数据准确及时，为业务分析提供稳定数据底座。', '1、本科及以上学历，熟悉数仓分层理论；2、精通SQL、Hive，熟悉Spark；3、了解ClickHouse/Doris等OLAP引擎；4、有BI报表开发经验优先。', 'ONLINE', 534,  0, '2026-04-20 10:00:00', '2026-08-28 14:00:00'),
(9,  3, '机器学习算法工程师',    '人工智能', 30, 50, '北京', '硕士', '3-5年', '负责机器学习/深度学习模型的设计、训练与上线，聚焦推荐、风控、CV等方向，推动算法能力业务落地。', '1、硕士及以上学历，计算机/数学相关专业；2、精通Python与TensorFlow/PyTorch；3、熟悉机器学习经典算法与特征工程；4、有顶会论文或大型落地项目优先。', 'ONLINE', 398,  0, '2026-05-06 09:00:00', '2026-09-04 10:00:00'),
(10, 4, '网络安全工程师',        '信息安全', 20, 35, '深圳', '本科', '1-3年', '负责客户系统的渗透测试、安全评估与漏洞修复验证，编写安全测试报告，参与安全运营应急响应。', '1、本科及以上学历，熟悉OWASP TOP10；2、掌握Web渗透测试流程与工具(Burp Suite、SQLMap等)；3、熟悉Python脚本编写；4、持有CISP/CISSP等证书者优先。', 'ONLINE', 620,  0, '2026-05-12 10:00:00', '2026-09-01 09:00:00'),
(11, 4, '信息安全咨询顾问',      '信息安全', 25, 45, '深圳', '本科', '3-5年', '为客户提供等级保护、风险评估与安全合规咨询服务，输出安全建设方案并推动客户落地。', '1、本科及以上学历，3年以上信息安全咨询经验；2、熟悉等保2.0、ISO27001；3、具备风险评估方法论与报告撰写能力；4、良好的客户沟通能力。', 'ONLINE', 287,  0, '2026-05-18 11:00:00', '2026-08-22 09:00:00'),
(12, 5, 'AI算法工程师',          '人工智能', 25, 45, '上海', '硕士', '1-3年', '负责NLP与大模型应用的算法研发，包括语义理解、RAG、Agent等方向的模型调优与工程落地。', '1、硕士及以上学历，NLP/深度学习方向；2、熟悉Transformer、PyTorch，了解主流大模型；3、有RAG、Agent、微调经验优先；4、较强的工程能力与论文阅读能力。', 'ONLINE', 734,  0, '2026-05-22 09:30:00', '2026-09-05 09:00:00'),
(13, 5, '测试开发工程师',        '测试',     12, 20, '上海', '本科', '1-3年', '负责AI平台与业务系统的自动化测试体系建设，开发测试工具与脚本，提升研发交付质量。', '1、本科及以上学历，2年以上测试开发经验；2、熟悉Java或Python；3、掌握Selenium、JMeter等工具；4、有接口自动化与CI集成经验。', 'ONLINE', 445,  0, '2026-06-02 10:00:00', '2026-08-30 14:00:00'),
(14, 5, '运维开发工程师',        '运维',     15, 25, '上海', '本科', '1-3年', '负责云平台与Kubernetes集群运维，建设CI/CD与监控告警体系，保障服务SLA与稳定性。', '1、本科及以上学历，熟悉Linux；2、掌握Docker、Kubernetes；3、熟悉Shell/Python/Go之一；4、有云原生监控(如Prometheus)经验优先。', 'ONLINE', 391,  0, '2026-06-08 09:00:00', '2026-09-02 10:00:00'),
(15, 6, 'Unity开发工程师',       '游戏开发', 18, 30, '广州', '本科', '1-3年', '负责手游客户端功能开发与性能优化，与策划、美术协作完成游戏玩法实现与上线维护。', '1、本科及以上学历，熟悉Unity3D引擎；2、扎实的C#功底，了解Lua热更；3、有完整上线项目经验优先；4、对游戏开发有热情。', 'ONLINE', 512,  0, '2026-06-12 14:00:00', '2026-09-03 09:00:00'),
(16, 1, 'Java开发实习生',        '后端开发', 4, 6, '上海', '本科', '在校生', '参与公司内部系统的Java后端开发，在导师指导下完成模块开发、单元测试与文档编写。', '1、计算机相关专业在读本科/硕士；2、掌握Java基础与Spring Boot；3、了解MySQL基本使用；4、每周可实习4天以上。', 'ONLINE', 903,  0, '2026-06-15 09:30:00', '2026-09-04 11:00:00'),
(17, 2, '产品经理',              '产品',     18, 28, '杭州', '本科', '3-5年', '负责电商SaaS产品规划与需求管理，输出PRD并协调研发测试上线，对产品指标负责。', '1、本科及以上学历，3年以上B端产品经验；2、熟悉电商或SaaS行业；3、熟练使用Axure等原型工具；4、良好的跨团队协作与数据思维。', 'ONLINE', 356,  0, '2026-06-20 10:00:00', '2026-08-26 09:00:00'),
(18, 3, '前端开发实习生',        '前端开发', 4, 7, '北京', '本科', '在校生', '参与数据中台Web前端开发，学习并实践Vue3工程化开发，协助完成页面与组件开发。', '1、计算机相关专业在读；2、掌握HTML/CSS/JavaScript基础；3、了解Vue框架者优先；4、学习能力强，能保证实习时间。', 'ONLINE', 628,  0, '2026-06-25 09:00:00', '2026-09-01 14:00:00'),
(19, 4, 'Java开发工程师(应届)',  '后端开发', 10, 16, '深圳', '本科', '应届', '面向应届毕业生，参与信息安全平台Java后端开发，接受系统培养，成长为独当一面的研发工程师。', '1、2026届本科及以上学历；2、扎实的Java与数据结构基础；3、了解Spring Boot、MySQL；4、对网络安全方向感兴趣优先。', 'ONLINE', 1052, 0, '2026-07-02 09:00:00', '2026-09-05 10:00:00'),
(20, 5, '软件测试工程师',        '测试',     10, 18, '上海', '本科', '1-3年', '负责AI应用产品的功能、接口与性能测试，编写测试用例并跟踪缺陷闭环，保障产品发布质量。', '1、本科及以上学历，1年以上测试经验；2、熟悉软件测试理论与流程；3、了解接口测试与SQL；4、有AI产品测试经验优先。', 'ONLINE', 302,  0, '2026-07-08 11:00:00', '2026-08-29 09:00:00'),
(21, 6, 'UI设计师',              '设计',     12, 20, '广州', '本科', '1-3年', '负责游戏与APP的UI视觉设计、交互规范制定，输出高保真设计稿并跟进开发还原度。', '1、设计相关专业本科；2、熟练使用Figma/Sketch/PS；3、有游戏或互联网产品UI经验；4、请随简历附作品集。', 'ONLINE', 268,  0, '2026-07-15 09:00:00', '2026-08-24 10:00:00'),
(22, 5, 'Node.js全栈开发工程师', '全栈开发', 20, 35, '上海', '本科', '3-5年', '负责AI应用的前后端全栈研发，使用Node.js+TypeScript构建服务端，配合Vue3完成功能闭环。', '1、本科及以上学历，3年以上全栈经验；2、精通Node.js/TypeScript；3、熟悉Vue3与Element Plus；4、熟悉MySQL、MongoDB与Redis。', 'ONLINE', 410,  0, '2026-07-20 10:30:00', '2026-09-06 09:00:00'),
(23, 6, 'Java游戏服务器开发工程师', '游戏开发', 20, 38, '广州', '本科', '3-5年', '负责游戏服务器核心玩法与战斗系统开发，使用Java与Netty构建高性能网络服务，保障线上稳定。', '1、本科及以上学历，3年以上游戏后端经验；2、精通Java与Netty网络编程；3、熟悉MySQL、Redis；4、有万人同服经验优先。', 'ONLINE', 335,  0, '2026-08-03 09:00:00', '2026-09-02 11:00:00'),
(24, 3, '后端开发工程师(成都)',  '后端开发', 12, 22, '成都', '本科', '1-3年', '负责数据产品后端服务开发，参与数据平台组件研发，技术栈以Java为主。', '1、本科及以上学历，1年以上Java开发经验；2、熟悉Spring Boot、MyBatis；3、熟悉MySQL、Redis；4、具备良好的编码规范与文档习惯。', 'ONLINE', 480,  0, '2026-08-10 10:00:00', '2026-09-07 09:00:00'),
(25, 2, '客服主管(校招)',        '运营',     7, 10, '杭州', '大专', '应届', '负责客服团队日常管理与培训，优化服务流程，提升客户满意度。', '1、2026届大专及以上学历；2、沟通表达能力强；3、有学生干部或实习经历优先。', 'OFFLINE', 96,   0, '2026-08-12 09:00:00', '2026-08-28 09:00:00');
