-- =============================================================
-- 智能招聘网站 - 初始化数据脚本
-- 数据库：smart_recruitment (MySQL 8.0 / utf8mb4)
-- 所有默认账号密码均为 123456 (BCrypt 加密存储)
-- =============================================================
USE smart_recruitment;

SET NAMES utf8mb4;

-- 通用业务账号密码(BCrypt, 明文 123456)
-- 1) 系统用户 sys_user

-- 2) 企业 company (与上面 role=COMPANY 的账号一一对应)

-- 3) 岗位 job (24个岗位)

-- 4) 岗位技能 job_skill
-- 5) 简历 resume

-- 6) 简历经历 resume_experience

-- 7) 职位投递 job_application

-- 8) 职位收藏 favorite

-- 9) AI 简历分析 ai_resume_analysis (便于演示, 仍可随时重新分析覆盖)

-- 10) AI 岗位推荐 ai_recommendation (便于首页演示, 可随点击刷新)

-- 11) 举报 report

-- 12) 系统日志 sys_log
